declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\ProjectionSettingsService;use App\Services\ProjectionLayoutService;Auth::requireAdmin();if($_SERVER['REQUEST_METHOD']!=='POST'||!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid request.');}$roundId=(int)($_POST['round_id']??0);$test=($_POST['data_mode']??'real')==='test';$pdo=Database::connection();$table=$test?'bdc_test_scoring_rounds':'bdc_scoring_rounds';$s=$pdo->prepare("SELECT COUNT(*) FROM {$table} WHERE id=:r");$s->execute(['r'=>$roundId]);if(!(int)$s->fetchColumn()){http_response_code(404);exit('Round not found.');}try{$settings=($_POST['action']??'apply')==='reset'?ProjectionSettingsService::reset($pdo,$roundId,$test,(int)(Auth::user()['id']??0)):ProjectionSettingsService::save($pdo,$roundId,$test,$_POST,(int)(Auth::user()['id']??0));$entryTable=$test?'bdc_test_scoring_entries':'bdc_scoring_entries';$c=$pdo->prepare("SELECT COUNT(*) FROM {$entryTable} WHERE round_id=:r AND entry_status='active'");$c->execute(['r'=>$roundId]);$count=(int)$c->fetchColumn();$layout=ProjectionLayoutService::resolve((string)$settings['screen_format'],max(1,$count),(string)$settings['density'],$settings['custom_width']?:(null),$settings['custom_height']?:(null));$_SESSION['projection_settings_notice']='Applied: '.$layout['format'].' · '.ucwords($layout['density']).' · '.$layout['columns'].' columns × '.$layout['rows'].' rows · '.$layout['pages'].' page'.($layout['pages']===1?'':'s');$target=$test?'test-control.php':'control.php';header('Location: '.$target.'?round_id='.$roundId,true,303);exit;}catch(Throwable $e){http_response_code(422);exit(e($e->getMessage()));}